using EasyData.Api.Data;using EasyData.Api.DTOs;using EasyData.Api.Services;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace EasyData.Api.Controllers;[ApiController][Route("api/auth")]public class AuthController(AppDbContext db,TokenService tokens):ControllerBase{[HttpPost("login")]public async Task<IActionResult> Login(LoginDto dto){var u=await db.Usuarios.FirstOrDefaultAsync(x=>x.NombreUsuario==dto.Usuario&&x.Activo);if(u is null)return Unauthorized();var h=new PasswordHasher<object>();if(h.VerifyHashedPassword(new object(),u.PasswordHash,dto.Password)==PasswordVerificationResult.Failed)return Unauthorized();return Ok(new{token=tokens.Crear(u),nombre=u.Nombre,rol=u.Rol});}}